import re


_VERSION_RE = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\Z")
_COMPARATOR_RE = re.compile(
    r"(>=|<=|>|<|=)(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\Z"
)


def satisfies(version: str, spec: str) -> bool:
    def parse_version(value: str) -> tuple[int, int, int]:
        if not isinstance(value, str):
            raise ValueError("version must be a string")
        match = _VERSION_RE.fullmatch(value)
        if not match:
            raise ValueError(f"malformed version: {value!r}")
        return tuple(map(int, match.groups()))

    if not isinstance(spec, str):
        raise ValueError("spec must be a string")

    actual = parse_version(version)
    text = spec.strip()
    if not text:
        raise ValueError("empty spec")

    if text.startswith("^") or text.startswith("~"):
        if len(text) < 2:
            raise ValueError(f"malformed spec: {spec!r}")

        base = parse_version(text[1:])
        lower = base

        if text[0] == "~":
            upper = (base[0], base[1] + 1, 0)
        elif base[0] > 0:
            upper = (base[0] + 1, 0, 0)
        elif base[1] > 0:
            upper = (0, base[1] + 1, 0)
        else:
            upper = (0, 0, base[2] + 1)

        return lower <= actual < upper

    tokens = text.split()
    if len(tokens) == 1:
        exact = _VERSION_RE.fullmatch(tokens[0])
        if exact:
            return actual == tuple(map(int, exact.groups()))

    if not tokens:
        raise ValueError(f"malformed spec: {spec!r}")

    for token in tokens:
        match = _COMPARATOR_RE.fullmatch(token)
        if not match:
            raise ValueError(f"malformed spec: {spec!r}")

        operator = match.group(1)
        target = tuple(map(int, match.groups()[1:]))

        if operator == ">=" and not (actual >= target):
            return False
        if operator == ">" and not (actual > target):
            return False
        if operator == "<=" and not (actual <= target):
            return False
        if operator == "<" and not (actual < target):
            return False
        if operator == "=" and not (actual == target):
            return False

    return True
